1	#!/usr/bin/env node
2	/**
3	 * source-capture.mjs — gate `source-capture` (contract `kumitate-source-capture-v1`, round 55).
4	 *
5	 * The opened-source byte-persistence gate. A SOURCES.md row is a claim; a URL alone is
6	 * not a resolvable location at closure — routed defect R54-C1: S108's rejection rested
7	 * on source bytes that were never committed, so a non-author spot-check could not
8	 * re-open the reject. This gate mechanically binds every opened SOURCES row to
9	 * committed capture bytes (or an explicit exemption) so any seat can re-open the
10	 * evidence exactly as it was read.
11	 *
12	 *   node scripts/source-capture.mjs [--registry <path>] [--sources <path>]
13	 *   node scripts/source-capture.mjs --selftest
14	 *
15	 * Verdicts (one line on stdout, after optional per-item notes on stdout):
16	 *   SOURCE_CAPTURE: CLEAN captures=<n> exemptions=<m>   exit 0
17	 *   SOURCE_CAPTURE: DRIFT captures=<n> exemptions=<m> bad=<k> first=<item:why>   exit 1
18	 *   SOURCE_CAPTURE: FAIL-CLOSED reason=<why>            exit 2 (could not evaluate)
19	 *   SOURCE_CAPTURE: USAGE ...                           exit 64
20	 *
21	 * Registry (default `.ufo/pins/source-captures.json`, lane-root-relative):
22	 *   { "version": 1,
23	 *     "captures":   [ { "sourceId": "S108", "path": "<repo-relative>", "sha256": "<64hex>",
24	 *                       "bytes": <n>, "captured": "YYYY-MM-DD" }, ... ],
25	 *     "exemptions": [ { "ids": ["S12"], "reason": "<why no committed capture>" }, ... ] }
26	 *
27	 * Sources document (default `corpus/SOURCES.md`, same base as the registry): the GFM
28	 * table rows are parsed for `| S### |` row ids; every row id must resolve to exactly
29	 * one binding — a capture entry or an exemption — and no binding may name a row that
30	 * does not exist.
31	 *
32	 * Rules:
33	 *   - `path` is resolved against the LANE ROOT for the default registry (paths are
34	 *     repo-relative); for an explicit `--registry`/`--sources` it is resolved against
35	 *     the registry file's own directory. An escaping path (`..` or absolute) is DRIFT
36	 *     `path-escape` — a capture must bind bytes beneath its base.
37	 *   - the resolved path must exist and be a REGULAR FILE — a symlinked capture is
38	 *     DRIFT `not-a-regular-file` (the capture binds bytes, not a name).
39	 *   - its sha256 (node:crypto over the exact bytes) must equal the capture entry;
40	 *     its byte length must equal `bytes`.
41	 *   - a capture entry whose file is absent is DRIFT `capture-absent`; a sha that does
42	 *     not match is DRIFT `hash-mismatch`; a wrong byte length is DRIFT `bytes-mismatch`.
43	 *   - a SOURCES row id with no capture and no exemption is DRIFT `uncaptured`.
44	 *   - a capture or exemption naming a row id absent from SOURCES.md is DRIFT
45	 *     `orphan-capture` / `orphan-exemption`.
46	 *   - duplicate `sourceId` values (inside captures, inside exemptions, or a sourceId in
47	 *     BOTH) make the registry malformed: FAIL-CLOSED — an ambiguous binding set cannot
48	 *     be evaluated.
49	 *   - an EMPTY captures array is DRIFT `captures-empty`, not CLEAN: a registry that
50	 *     binds nothing is precisely the state this gate exists to catch.
51	 *   - registry unreadable / not JSON / version !== 1, or sources doc unreadable /
52	 *     unparseable → FAIL-CLOSED (exit 2, never a score).
53	 *
54	 * The gate never writes. It reads the registry, the sources doc and the captured
55	 * bytes only.
56	 *
57	 * Selftest: hermetic fixtures under mkdtemp (the gate binary run as a subprocess
58	 * against crafted registries + sources docs), thirteen cases, one red-before per rule;
59	 * the final line reads `SOURCE_CAPTURE_SELFTEST: PASS (13/13)` + `VERDICT: PASS`, exit 0.
60	 *
61	 * Exit map: 0 clean · 1 a real defect (drift) · 2 fail-closed · 64 usage.
62	 * Owner: kumitate L1. Row: SKILL.md §Gate registry (`source-capture`, gate);
63	 * pin: SCORECARD.md `kumitate-gate-pins-v1` (`pin.source-capture`).
64	 */
65	import { spawnSync } from 'node:child_process';
66	import { createHash } from 'node:crypto';
67	import { lstatSync, mkdtempSync, mkdirSync, readFileSync, realpathSync, rmSync, symlinkSync, writeFileSync } from 'node:fs';
68	import { dirname, join, relative, resolve, sep } from 'node:path';
69	import { tmpdir } from 'node:os';
70	import { fileURLToPath } from 'node:url';
71	
72	const SELF = fileURLToPath(import.meta.url);
73	const LANE = resolve(dirname(SELF), '..');
74	const DEFAULT_REGISTRY = '.ufo/pins/source-captures.json';
75	const DEFAULT_SOURCES = 'corpus/SOURCES.md';
76	const HEX64 = /^[0-9a-f]{64}$/;
77	const SID = /^S[0-9]{3,}$/;
78	
79	const sha = (b) => createHash('sha256').update(b).digest('hex');
80	
81	function usage() {
82	  process.stderr.write('SOURCE_CAPTURE: USAGE node scripts/source-capture.mjs [--registry <path>] [--sources <path>] | --selftest\n');
83	  process.exit(64);
84	}
85	
86	function loadRegistry(regPath) {
87	  let raw;
88	  try {
89	    if (!lstatSync(regPath).isFile()) {
90	      return { ok: false, reason: 'registry not a regular file' };
91	    }
92	    raw = readFileSync(regPath);
93	  } catch (e) {
94	    return { ok: false, reason: `registry unreadable: ${e.code || 'EIO'}` };
95	  }
96	  let doc;
97	  try {
98	    doc = JSON.parse(raw.toString('utf8'));
99	  } catch {
100	    return { ok: false, reason: 'registry not valid JSON' };
101	  }
102	  if (!doc || typeof doc !== 'object' || Array.isArray(doc)) {
103	    return { ok: false, reason: 'registry not an object' };
104	  }
105	  if (doc.version !== 1) {
106	    return { ok: false, reason: `registry version ${JSON.stringify(doc.version)} !== 1` };
107	  }
108	  if (!Array.isArray(doc.captures)) {
109	    return { ok: false, reason: 'registry captures not an array' };
110	  }
111	  if (!Array.isArray(doc.exemptions)) {
112	    return { ok: false, reason: 'registry exemptions not an array' };
113	  }
114	  const ids = new Set();
115	  for (const c of doc.captures) {
116	    if (!c || typeof c !== 'object' || typeof c.sourceId !== 'string' || !SID.test(c.sourceId)
117	        || typeof c.path !== 'string' || c.path.length === 0
118	        || typeof c.sha256 !== 'string' || !HEX64.test(c.sha256)
119	        || !Number.isSafeInteger(c.bytes) || c.bytes < 0
120	        || typeof c.captured !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(c.captured)) {
121	      return { ok: false, reason: 'a capture entry lacks valid sourceId/path/sha256(64hex)/bytes/captured' };
122	    }
123	    if (ids.has(c.sourceId)) {
124	      return { ok: false, reason: `duplicate sourceId ${JSON.stringify(c.sourceId)}` };
125	    }
126	    ids.add(c.sourceId);
127	  }
128	  for (const x of doc.exemptions) {
129	    if (!x || typeof x !== 'object' || !Array.isArray(x.ids) || x.ids.length === 0
130	        || typeof x.reason !== 'string' || x.reason.length === 0) {
131	      return { ok: false, reason: 'an exemption entry lacks valid ids/reason' };
132	    }
133	    for (const id of x.ids) {
134	      if (typeof id !== 'string' || !SID.test(id)) {
135	        return { ok: false, reason: `exemption id ${JSON.stringify(id)} is not an S### row id` };
136	      }
137	      if (ids.has(id)) {
138	        return { ok: false, reason: `duplicate sourceId ${JSON.stringify(id)}` };
139	      }
140	      ids.add(id);
141	    }
142	  }
143	  return { ok: true, captures: doc.captures, exemptions: doc.exemptions };
144	}
145	
146	function loadSourceIds(srcPath) {
147	  let raw;
148	  try {
149	    if (!lstatSync(srcPath).isFile()) {
150	      return { ok: false, reason: 'sources doc not a regular file' };
151	    }
152	    raw = readFileSync(srcPath, 'utf8');
153	  } catch (e) {
154	    return { ok: false, reason: `sources doc unreadable: ${e.code || 'EIO'}` };
155	  }
156	  const ids = new Set();
157	  for (const m of raw.matchAll(/^\s*\|\s*(S[0-9]{3,})\s*\|/gm)) {
158	    if (ids.has(m[1])) {
159	      return { ok: false, reason: `sources doc has duplicate row id ${m[1]}` };
160	    }
161	    ids.add(m[1]);
162	  }
163	  if (ids.size === 0) {
164	    return { ok: false, reason: 'sources doc carries no S### rows' };
165	  }
166	  return { ok: true, ids };
167	}
168	
169	function evaluate(registryPath, sourcesPath) {
170	  const reg = loadRegistry(registryPath);
171	  if (!reg.ok) {
172	    return { verdict: 'FAIL-CLOSED', reason: reg.reason, exit: 2 };
173	  }
174	  const src = loadSourceIds(sourcesPath);
175	  if (!src.ok) {
176	    return { verdict: 'FAIL-CLOSED', reason: src.reason, exit: 2 };
177	  }
178	  if (reg.captures.length === 0) {
179	    return { verdict: 'DRIFT', captures: 0, exemptions: reg.exemptions.reduce((n, x) => n + x.ids.length, 0),
180	      bad: ['captures-empty:registry binds nothing'], exit: 1 };
181	  }
182	  // Path base: repo-relative against the lane root for the default registry;
183	  // registry-local for an explicit --registry (selftest fixtures, out-of-tree audits).
184	  const isDefault = resolve(registryPath) === join(LANE, DEFAULT_REGISTRY);
185	  const base = isDefault ? LANE : dirname(resolve(registryPath));
186	  let baseReal;
187	  try {
188	    baseReal = realpathSync(base);
189	  } catch (e) {
190	    return { verdict: 'FAIL-CLOSED', reason: `path base unreadable: ${e.code || 'EIO'}`, exit: 2 };
191	  }
192	  const bad = [];
193	  for (const c of reg.captures) {
194	    const abs = resolve(base, c.path);
195	    let targetReal;
196	    try {
197	      targetReal = realpathSync(abs);
198	    } catch {
199	      bad.push(`${c.sourceId}:capture-absent`);
200	      continue;
201	    }
202	    const rel = relative(baseReal, targetReal);
203	    if (rel === '..' || rel.startsWith(`..${sep}`) || rel.includes(`${sep}..${sep}`)) {
204	      bad.push(`${c.sourceId}:path-escape`);
205	      continue;
206	    }
207	    let st;
208	    try {
209	      st = lstatSync(abs);
210	    } catch {
211	      bad.push(`${c.sourceId}:capture-absent`);
212	      continue;
213	    }
214	    if (!st.isFile()) {
215	      bad.push(`${c.sourceId}:not-a-regular-file`);
216	      continue;
217	    }
218	    let bytes;
219	    try {
220	      bytes = readFileSync(abs);
221	    } catch (e) {
222	      return { verdict: 'FAIL-CLOSED', reason: `${c.sourceId}: unreadable: ${e.code || 'EIO'}`, exit: 2 };
223	    }
224	    if (bytes.length !== c.bytes) {
225	      bad.push(`${c.sourceId}:bytes-mismatch`);
226	      continue;
227	    }
228	    if (sha(bytes) !== c.sha256) {
229	      bad.push(`${c.sourceId}:hash-mismatch`);
230	      continue;
231	    }
232	  }
233	  const bound = new Set([
234	    ...reg.captures.map((c) => c.sourceId),
235	    ...reg.exemptions.flatMap((x) => x.ids),
236	  ]);
237	  for (const id of src.ids) {
238	    if (!bound.has(id)) bad.push(`${id}:uncaptured`);
239	  }
240	  for (const id of bound) {
241	    if (!src.ids.has(id)) {
242	      const isCap = reg.captures.some((c) => c.sourceId === id);
243	      bad.push(`${id}:${isCap ? 'orphan-capture' : 'orphan-exemption'}`);
244	    }
245	  }
246	  const exCount = reg.exemptions.reduce((n, x) => n + x.ids.length, 0);
247	  if (bad.length > 0) {
248	    return { verdict: 'DRIFT', captures: reg.captures.length, exemptions: exCount, bad, exit: 1 };
249	  }
250	  return { verdict: 'CLEAN', captures: reg.captures.length, exemptions: exCount, exit: 0 };
251	}
252	
253	function emit(result) {
254	  if (result.verdict === 'CLEAN') {
255	    process.stdout.write(`SOURCE_CAPTURE: CLEAN captures=${result.captures} exemptions=${result.exemptions}\n`);
256	  } else if (result.verdict === 'DRIFT') {
257	    for (const b of result.bad.slice(1)) process.stdout.write(`SOURCE_CAPTURE: note ${b}\n`);
258	    process.stdout.write(`SOURCE_CAPTURE: DRIFT captures=${result.captures} exemptions=${result.exemptions} bad=${result.bad.length} first=${result.bad[0]}\n`);
259	  } else {
260	    process.stdout.write(`SOURCE_CAPTURE: FAIL-CLOSED reason=${result.reason}\n`);
261	  }
262	  process.exit(result.exit);
263	}
264	
265	function selftest() {
266	  const root = mkdtempSync(join(tmpdir(), 'source-capture-st.'));
267	  const results = [];
268	  const pass = (name, ok, detail) => {
269	    results.push({ name, ok });
270	    process.stdout.write(`case ${name}: ${ok ? 'PASS' : `FAIL ${detail || ''}`}\n`);
271	  };
272	  const run = (args, opts = {}) => spawnSync(process.execPath, [SELF, ...args],
273	    { encoding: 'utf8', timeout: 60_000, ...opts });
274	  const last = (r) => `${r.stdout || ''}`.trim().split('\n').pop() || '';
275	  const shaHex = (s) => sha(Buffer.from(s, 'utf8'));
276	
277	  const fixture = (dir) => {
278	    mkdirSync(dir, { recursive: true });
279	    writeFileSync(join(dir, 'sources.md'),
280	      '| id | source | kind | tier | scope | anchor | teaches | status | opened | recheck | used-by |\n'
281	      + '|---|---|---|---|---|---|---|---|---|---|---|\n'
282	      + '| S001 | alpha | docs | A | s | a | t | mined | 2026-01-01 | 90d | p |\n'
283	      + '| S002 | beta | docs | A | s | a | t | mined | 2026-01-01 | 90d | p |\n'
284	      + '| S003 | gamma | docs | B | s | a | t | rejected | 2026-01-01 | 90d | p |\n');
285	    writeFileSync(join(dir, 'cap-a.txt'), 'alpha capture bytes\n');
286	    writeFileSync(join(dir, 'cap-b.txt'), 'beta capture bytes\n');
287	    const reg = {
288	      version: 1,
289	      captures: [
290	        { sourceId: 'S001', path: 'cap-a.txt', sha256: shaHex('alpha capture bytes\n'), bytes: 20, captured: '2026-10-24' },
291	        { sourceId: 'S002', path: 'cap-b.txt', sha256: shaHex('beta capture bytes\n'), bytes: 19, captured: '2026-10-24' },
292	      ],
293	      exemptions: [{ ids: ['S003'], reason: 'rejected rows keep no capture yet' }],
294	    };
295	    writeFileSync(join(dir, 'reg.json'), JSON.stringify(reg, null, 2));
296	    return { reg: join(dir, 'reg.json'), src: join(dir, 'sources.md') };
297	  };
298	
299	  try {
300	    // case 1 — clean fixture: CLEAN captures=2 exemptions=1, exit 0
301	    {
302	      const d = join(root, 'd1'); const f = fixture(d);
303	      const r = run(['--registry', f.reg, '--sources', f.src]);
304	      pass('clean', r.status === 0 && last(r) === 'SOURCE_CAPTURE: CLEAN captures=2 exemptions=1',
305	        `exit=${r.status} last=${JSON.stringify(last(r))}`);
306	    }
307	    // case 2 — hash flip: DRIFT hash-mismatch, exit 1
308	    {
309	      const d = join(root, 'd2'); const f = fixture(d);
310	      const reg = JSON.parse(readFileSync(f.reg, 'utf8'));
311	      reg.captures[0].sha256 = '0'.repeat(64);
312	      writeFileSync(f.reg, JSON.stringify(reg));
313	      const r = run(['--registry', f.reg, '--sources', f.src]);
314	      pass('hash-mismatch', r.status === 1 && last(r).includes('S001:hash-mismatch'),
315	        `exit=${r.status} last=${JSON.stringify(last(r))}`);
316	    }
317	    // case 3 — captured file deleted: DRIFT capture-absent
318	    {
319	      const d = join(root, 'd3'); const f = fixture(d);
320	      rmSync(join(d, 'cap-a.txt'));
321	      const r = run(['--registry', f.reg, '--sources', f.src]);
322	      pass('capture-absent', r.status === 1 && last(r).includes('S001:capture-absent'),
323	        `exit=${r.status} last=${JSON.stringify(last(r))}`);
324	    }
325	    // case 4 — symlink capture: DRIFT not-a-regular-file
326	    {
327	      const d = join(root, 'd4'); const f = fixture(d);
328	      rmSync(join(d, 'cap-a.txt'));
329	      symlinkSync(join(d, 'cap-b.txt'), join(d, 'cap-a.txt'));
330	      const r = run(['--registry', f.reg, '--sources', f.src]);
331	      pass('not-a-regular-file', r.status === 1 && last(r).includes('S001:not-a-regular-file'),
332	        `exit=${r.status} last=${JSON.stringify(last(r))}`);
333	    }
334	    // case 5 — wrong bytes count: DRIFT bytes-mismatch
335	    {
336	      const d = join(root, 'd5'); const f = fixture(d);
337	      const reg = JSON.parse(readFileSync(f.reg, 'utf8'));
338	      reg.captures[0].bytes = 999;
339	      writeFileSync(f.reg, JSON.stringify(reg));
340	      const r = run(['--registry', f.reg, '--sources', f.src]);
341	      pass('bytes-mismatch', r.status === 1 && last(r).includes('S001:bytes-mismatch'),
342	        `exit=${r.status} last=${JSON.stringify(last(r))}`);
343	    }
344	    // case 6 — escaping path: DRIFT path-escape
345	    {
346	      const d = join(root, 'd6'); const f = fixture(d);
347	      writeFileSync(join(root, 'outside.txt'), 'alpha capture bytes\n');
348	      const reg = JSON.parse(readFileSync(f.reg, 'utf8'));
349	      reg.captures[0].path = '../outside.txt';
350	      writeFileSync(f.reg, JSON.stringify(reg));
351	      const r = run(['--registry', f.reg, '--sources', f.src]);
352	      pass('path-escape', r.status === 1 && /S001:path-escape/.test(last(r)),
353	        `exit=${r.status} last=${JSON.stringify(last(r))}`);
354	    }
355	    // case 7 — SOURCES row with no binding: DRIFT uncaptured
356	    {
357	      const d = join(root, 'd7'); const f = fixture(d);
358	      writeFileSync(join(d, 'sources.md'), readFileSync(join(d, 'sources.md'), 'utf8')
359	        + '| S009 | iota | docs | A | s | a | t | mined | 2026-01-01 | 90d | p |\n');
360	      const r = run(['--registry', f.reg, '--sources', join(d, 'sources.md')]);
361	      pass('uncaptured', r.status === 1 && last(r).includes('S009:uncaptured'),
362	        `exit=${r.status} last=${JSON.stringify(last(r))}`);
363	    }
364	    // case 8 — capture for a non-existent row: DRIFT orphan-capture
365	    {
366	      const d = join(root, 'd8'); const f = fixture(d);
367	      const reg = JSON.parse(readFileSync(f.reg, 'utf8'));
368	      reg.captures.push({ sourceId: 'S008', path: 'cap-b.txt', sha256: shaHex('beta capture bytes\n'), bytes: 19, captured: '2026-10-24' });
369	      writeFileSync(f.reg, JSON.stringify(reg));
370	      const r = run(['--registry', f.reg, '--sources', f.src]);
371	      pass('orphan-capture', r.status === 1 && last(r).includes('S008:orphan-capture'),
372	        `exit=${r.status} last=${JSON.stringify(last(r))}`);
373	    }
374	    // case 9 — empty captures: DRIFT captures-empty
375	    {
376	      const d = join(root, 'd9'); const f = fixture(d);
377	      const reg = JSON.parse(readFileSync(f.reg, 'utf8'));
378	      reg.captures = [];
379	      reg.exemptions = [{ ids: ['S001', 'S002', 'S003'], reason: 'all exempt' }];
380	      writeFileSync(f.reg, JSON.stringify(reg));
381	      const r = run(['--registry', f.reg, '--sources', f.src]);
382	      pass('captures-empty', r.status === 1 && last(r).includes('captures-empty'),
383	        `exit=${r.status} last=${JSON.stringify(last(r))}`);
384	    }
385	    // case 10 — malformed JSON: FAIL-CLOSED exit 2
386	    {
387	      const d = join(root, 'd10'); const f = fixture(d);
388	      writeFileSync(f.reg, '{ broken');
389	      const r = run(['--registry', f.reg, '--sources', f.src]);
390	      pass('registry-not-json', r.status === 2 && /FAIL-CLOSED reason=registry not valid JSON/.test(last(r)),
391	        `exit=${r.status} last=${JSON.stringify(last(r))}`);
392	    }
393	    // case 11 — version !== 1: FAIL-CLOSED exit 2
394	    {
395	      const d = join(root, 'd11'); const f = fixture(d);
396	      const reg = JSON.parse(readFileSync(f.reg, 'utf8'));
397	      reg.version = 2;
398	      writeFileSync(f.reg, JSON.stringify(reg));
399	      const r = run(['--registry', f.reg, '--sources', f.src]);
400	      pass('registry-version', r.status === 2 && /FAIL-CLOSED reason=registry version 2 !== 1/.test(last(r)),
401	        `exit=${r.status} last=${JSON.stringify(last(r))}`);
402	    }
403	    // case 12 — capture+exempt conflict: FAIL-CLOSED exit 2
404	    {
405	      const d = join(root, 'd12'); const f = fixture(d);
406	      const reg = JSON.parse(readFileSync(f.reg, 'utf8'));
407	      reg.exemptions.push({ ids: ['S001'], reason: 'conflict' });
408	      writeFileSync(f.reg, JSON.stringify(reg));
409	      const r = run(['--registry', f.reg, '--sources', f.src]);
410	      pass('capture-exempt-conflict', r.status === 2 && /FAIL-CLOSED reason=duplicate sourceId "S001"/.test(last(r)),
411	        `exit=${r.status} last=${JSON.stringify(last(r))}`);
412	    }
413	    // case 13 — sources doc missing: FAIL-CLOSED exit 2
414	    {
415	      const d = join(root, 'd13'); const f = fixture(d);
416	      rmSync(f.src);
417	      const r = run(['--registry', f.reg, '--sources', f.src]);
418	      pass('sources-absent', r.status === 2 && /FAIL-CLOSED/.test(last(r)),
419	        `exit=${r.status} last=${JSON.stringify(last(r))}`);
420	    }
421	  } finally {
422	    rmSync(root, { recursive: true, force: true });
423	  }
424	  const held = results.filter((r) => r.ok).length;
425	  process.stdout.write(`SOURCE_CAPTURE_SELFTEST: ${held === results.length ? 'PASS' : 'FAIL'} (${held}/${results.length})\n`);
426	  process.stdout.write(`VERDICT: ${held === results.length ? 'PASS' : 'FAIL'}\n`);
427	  process.exit(held === results.length ? 0 : 1);
428	}
429	
430	const argv = process.argv.slice(2);
431	if (argv.includes('--selftest')) {
432	  selftest();
433	} else {
434	  let reg = join(LANE, DEFAULT_REGISTRY);
435	  let src = join(LANE, DEFAULT_SOURCES);
436	  let explicitReg = false;
437	  for (let i = 0; i < argv.length; i++) {
438	    if (argv[i] === '--registry') {
439	      if (i + 1 >= argv.length) usage();
440	      reg = resolve(argv[++i]); explicitReg = true;
441	    } else if (argv[i] === '--sources') {
442	      if (i + 1 >= argv.length) usage();
443	      src = resolve(argv[++i]);
444	    } else {
445	      usage();
446	    }
447	  }
448	  // With an explicit registry the sources doc defaults to registry-local unless named.
449	  if (explicitReg && !argv.includes('--sources')) {
